def compute(vars):
    value = round(sum([vars["v1"]]), 3)
    return {
        "value": value,
        "trace": {
            "v1": vars["v1"],
            "sum": value,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": "monetary"
            }
        }
    }
